// ── Build the Apify actor call from Whizz's deeper-search enrichment request ──
// apify/google-search-scraper takes a newline-separated block of search queries and returns one
// dataset item per query (organic results, ads, etc. for that query). No API token here — Call
// Apify Google Search Actor authenticates via n8n's native Apify credential (Authentication:
// Predefined Credential Type → Apify API) instead of a token in code.
const body = $('Webhook').first().json.body || {};

// Same cap the Worker already applies before calling this webhook — kept here too since this
// workflow could in principle be called directly.
const MAX_LEADS = 15;
const leads = (Array.isArray(body.leads) ? body.leads : [])
  .map(l => ({ key: String(l?.key || '').trim(), query: String(l?.query || '').trim() }))
  .filter(l => l.key && l.query)
  .slice(0, MAX_LEADS);

const ACTOR_ID = 'apify~google-search-scraper';

return [{
  json: {
    actorId: ACTOR_ID,
    keys: leads.map(l => l.key),
    queries: leads.map(l => l.query),
    actorInput: {
      queries: leads.map(l => l.query).join('\n'),
      resultsPerPage: 10,
      maxPagesPerQuery: 1,
      languageCode: 'en',
      mobileResults: false
    }
  }
}];

// ── Match Apify's dataset items back to Whizz's leads and pull out any WhatsApp/Telegram link ──
const items = $input.all();
let rawItems = [];
let apiError = null;

for (const item of items) {
  const j = item.json;
  if (j && j.error) { apiError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); continue; }
  if (Array.isArray(j)) rawItems.push(...j);
  else if (j) rawItems.push(j);
}

if (apiError) {
  return [{ json: { results: {}, error: `Google Search/Apify error: ${apiError}` } }];
}

const built = $('Build Apify Request').first().json;
const keys = built.keys || [];
const queries = built.queries || [];

// google-search-scraper's exact output schema isn't verified against a live run from this
// codebase (apify.com is unreachable here) — try to match each dataset item back to the lead
// whose query produced it via whatever query-echo field it carries, and fall back to positional
// order (the actor is documented to return one item per input query, in order) when that field
// isn't present under any of the likely names.
function resolveKey(rawItem, index) {
  const term = rawItem?.searchQuery?.term || rawItem?.searchQuery?.q || rawItem?.term || rawItem?.query || '';
  if (term) {
    const qIndex = queries.findIndex(q => q === term);
    if (qIndex !== -1) return keys[qIndex];
  }
  return keys[index] || null;
}

const TELEGRAM_RE = /https?:\/\/(?:t|telegram)\.me\/([A-Za-z0-9_]{4,32})/i;
const WA_ME_RE = /https?:\/\/(?:api\.)?wa\.me\/(\+?[0-9][0-9\s\-()]{5,17}[0-9])/i;
const WA_API_RE = /https?:\/\/api\.whatsapp\.com\/send\/?\?phone=(\+?[0-9][0-9\s\-()]{5,17}[0-9])/i;

// Scanning the whole stringified item (not a specific 'snippet'/'description' field) is
// deliberate — it's resilient to this actor's exact field names being wrong/renamed, at the
// cost of an occasional false match inside an unrelated URL param, which is an acceptable
// trade for a best-effort enrichment pass.
const results = {};
rawItems.forEach((rawItem, index) => {
  const key = resolveKey(rawItem, index);
  if (!key) return;
  const haystack = JSON.stringify(rawItem);
  const tg = haystack.match(TELEGRAM_RE);
  const waMe = haystack.match(WA_ME_RE);
  const waApi = haystack.match(WA_API_RE);
  const whatsappRaw = (waMe && waMe[1]) || (waApi && waApi[1]) || '';
  const hit = {
    telegram: tg ? tg[1] : '',
    whatsapp: whatsappRaw.replace(/[^0-9+]/g, '')
  };
  if (hit.telegram || hit.whatsapp) results[key] = hit;
});

return [{ json: { results } }];
